package tw.com.tft.documentscanner.session;
import android.content.*;import android.net.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.UUID;import tw.com.tft.documentscanner.model.*;
public class ScanSessionStore{private static ScanSessionStore instance;private ScanSession session=new ScanSession();public static synchronized ScanSessionStore get(Context c){if(instance==null){instance=new ScanSessionStore();instance.load(c.getApplicationContext());}return instance;}public synchronized ScanSession session(){return session;}public synchronized void startNew(Context c,String s){clearFiles(c);session=new ScanSession();session.sessionSource=s;persist(c);}public synchronized ScanItem importUri(Context c,Uri u,String s)throws Exception{File d=new File(c.getCacheDir(),"scan_originals");if(!d.exists()&&!d.mkdirs())throw new IllegalStateException("cache");File f=new File(d,UUID.randomUUID()+".jpg");try(InputStream in=c.getContentResolver().openInputStream(u);FileOutputStream out=new FileOutputStream(f)){if(in==null)throw new IllegalArgumentException("image");byte[] b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);}ScanItem i=new ScanItem(f.getAbsolutePath());i.sourceType=s;session.items.add(i);persist(c);return i;}public synchronized ScanItem addLocalFile(Context c,File f,String s){ScanItem i=new ScanItem(f.getAbsolutePath());i.sourceType=s;session.items.add(i);persist(c);return i;}public synchronized void persist(Context c){try{JSONObject r=new JSONObject();r.put("currentIndex",session.currentIndex);r.put("sessionSource",session.sessionSource);JSONArray a=new JSONArray();for(ScanItem i:session.items)a.put(i.toJson());r.put("items",a);try(FileOutputStream o=new FileOutputStream(new File(c.getFilesDir(),"scan_session.json"))){o.write(r.toString().getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}public synchronized void clear(Context c){clearFiles(c);session=new ScanSession();new File(c.getFilesDir(),"scan_session.json").delete();}private void load(Context c){File f=new File(c.getFilesDir(),"scan_session.json");if(!f.exists())return;try(FileInputStream in=new FileInputStream(f)){byte[] b=new byte[(int)f.length()];int n=in.read(b);JSONObject r=new JSONObject(new String(b,0,n,StandardCharsets.UTF_8));ScanSession s=new ScanSession();s.currentIndex=r.optInt("currentIndex",0);s.sessionSource=r.optString("sessionSource","GALLERY");JSONArray a=r.optJSONArray("items");if(a!=null)for(int x=0;x<a.length();x++){ScanItem i=ScanItem.fromJson(a.getJSONObject(x));if(new File(i.sourcePath).exists())s.items.add(i);}if(!s.items.isEmpty())s.currentIndex=Math.min(s.currentIndex,s.items.size()-1);session=s;}catch(Exception e){session=new ScanSession();}}private void clearFiles(Context c){del(new File(c.getCacheDir(),"scan_originals"));del(new File(c.getCacheDir(),"scan_outputs"));del(new File(c.getCacheDir(),"scan_share"));}private static void del(File d){if(!d.exists())return;File[] f=d.listFiles();if(f==null)return;for(File x:f){if(x.isDirectory())del(x);x.delete();}}}